from _lib import *
MM='Manuel des Monstres 5e (2014)'
I(1,'Dans D&D 5e, lequel de ces monstres n’est pas une construction ?','Zombie',['Golem d’argile','Armure animée','Homoncule'],'Le zombie est un mort-vivant ; les trois autres sont des constructions.',MM+', entrées correspondantes')
I(2,'Dans D&D 5e, lequel de ces monstres n’est pas un golem ?','Armure animée',['Golem de chair','Golem de pierre','Golem de fer'],'L’armure animée est une construction, mais pas un golem.',MM+', entrées correspondantes')
I(3,'Lequel de ces éléments n’a pas été introduit par Eberron: Rising from the Last War ?','Barde',['Artificier','Forgé','Changelin'],'Le barde existe depuis le Manuel des Joueurs ; artificier, forgé et changelin viennent d’Eberron.','Eberron: Rising from the Last War (2019)')
T(1,'Dans D&D 5e, le golem de ____ est assemblé à partir de morceaux de cadavres.','chair',['pierre','fer','argile'],'Le golem de chair est un monstre de Frankenstein.',MM+', entrée « Golem de chair »')
T(2,'Dans D&D 5e, le golem de ____ est le plus puissant du Manuel des Monstres, avec un FP de 16.','fer',['pierre','chair','argile'],'Le golem de fer (FP 16) crache un gaz empoisonné.',MM+', entrée « Golem de fer »')
