M(2,'Dans D&D 5e, lesquels de ces monstres sont des constructions ? (plusieurs bonnes réponses)',['Golem de chair','Armure animée','Homoncule'],['Gargouille','Zombie'],'Golem de chair, armure animée et homoncule sont des constructions ; gargouille et zombie non.',MM+', entrées correspondantes')
M(3,'Dans D&D 5e, lesquels de ces golems ont un FP d’au moins 9 ? (plusieurs bonnes réponses)',['Golem d’argile','Golem de pierre','Golem de fer'],['Golem de chair','Armure animée'],'FP : argile 9, pierre 10, fer 16 ; chair 5 et armure animée 1.',MM+', blocs de caractéristiques')
M(3,'Dans D&D 5e, lesquels de ces golems sont soignés par un type de dégâts ? (plusieurs bonnes réponses)',['Golem de chair','Golem de fer','Golem d’argile'],['Golem de pierre','Armure animée'],'Chair : foudre ; fer : feu ; argile : acide. Pierre et armure animée n’ont pas ce trait.',MM+', blocs de caractéristiques')
O(2,'Classe ces golems par FP croissant.',['Armure animée','Golem de chair','Golem d’argile','Golem de pierre','Golem de fer'],'FP : armure animée 1, chair 5, argile 9, pierre 10, fer 16.',MM+', blocs de caractéristiques')
O(3,'Classe ces golems par points de vie moyens croissants.',['Golem de chair','Golem d’argile','Golem de pierre','Golem de fer'],'PV moyens : chair 93, argile 133, pierre 178, fer 210.',MM+', blocs de caractéristiques')
A(2,'Associe chaque golem au dégât qui le soigne.',[('Golem de chair','Foudre'),('Golem de fer','Feu'),('Golem d’argile','Acide'),('Golem de pierre','Aucun')],'Chair : foudre ; fer : feu ; argile : acide ; pierre ne se soigne pas par un type de dégâts.',MM+', blocs de caractéristiques')
A(1,'Associe chaque construction à sa description.',[('Golem de chair','Cadavres assemblés'),('Armure animée','Armure qui attaque'),('Homoncule','Minuscule serviteur'),('Épée volante','Arme animée')],'Chaque construction possède une silhouette ou une fonction propre.',MM+', entrées correspondantes')
W(1,['Je suis une construction.','Mon corps est fait de morceaux de cadavres.','La foudre me soigne.'],'Golem de chair',['Zombie','Golem d’argile','Ghoule'],'Le golem de chair puise sa force dans la foudre.',MM+', entrée « Golem de chair »')
W(2,['Je suis une construction de FP 16.','Je crache un gaz empoisonné.','Le feu me soigne.'],'Golem de fer',['Golem de pierre','Golem d’argile','Gardien-bouclier'],'Le golem de fer est le plus puissant des golems du Manuel des Monstres.',MM+', entrée « Golem de fer »')
W(3,['Je suis un soldat artificiel.','Je suis né de la Guerre du Dernier Jour.','Mon corps est fait de bois, de pierre et de métal.'],'Forgé',['Changelin','Kalashtar','Homoncule'],'Les forgés sont des constructions vivantes d’Eberron.','Eberron: Rising from the Last War (2019)')
save('golems-constructions','gol')
